def copy_from_profile(apps, schema_editor):
    Profile = apps.get_model("accounts", "Profile")
    AccountIdentity = apps.get_model("accounts", "AccountIdentity")
    AccountLifecycle = apps.get_model("accounts", "AccountLifecycle")

    identities, lifecycles = [], []
    for p in Profile.objects.all().iterator():
        identities.append(AccountIdentity(
            user_id=p.user_id,
            real_name=p.real_name or "",
            identity=p.identity or "",
            pending_card_no=p.card_no or "",
        ))
        lifecycles.append(AccountLifecycle(
            user_id=p.user_id,
            registration_deadline=p.registration_deadline,
            expiry_disabled_at=p.expiry_disabled_at,
            deleted_at=p.deleted_at,
            validity_notice_ack=p.validity_notice_ack or "",
            must_change_password=p.must_change_password,
        ))

    AccountIdentity.objects.bulk_create(identities, batch_size=500, ignore_conflicts=True)
    AccountLifecycle.objects.bulk_create(lifecycles, batch_size=500, ignore_conflicts=True)
    print(
        f"[accounts.0034] 回填 {len(identities)} 行实名 + "
        f"{len(lifecycles)} 行生命周期（Profile 共 {len(identities)} 行）"
    )


def copy_back_to_profile(apps, schema_editor):
    """反向：新表写回旧列。回滚后 Profile 仍是唯一真源。"""
    Profile = apps.get_model("accounts", "Profile")
    AccountIdentity = apps.get_model("accounts", "AccountIdentity")
    AccountLifecycle = apps.get_model("accounts", "AccountLifecycle")

    for row in AccountIdentity.objects.all().iterator():
        Profile.objects.filter(user_id=row.user_id).update(
            real_name=row.real_name,
            identity=row.identity,
            card_no=row.pending_card_no,
        )
    for row in AccountLifecycle.objects.all().iterator():
        Profile.objects.filter(user_id=row.user_id).update(
            registration_deadline=row.registration_deadline,
            expiry_disabled_at=row.expiry_disabled_at,
            deleted_at=row.deleted_at,
            validity_notice_ack=row.validity_notice_ack,
            must_change_password=row.must_change_password,
        )


